-- =====================================================================
-- ALDEA — traer al sitio nuevo las imagenes que aun vivian en el
-- WordPress viejo (aldea.work/wp-content/uploads/...).
-- Los archivos ya se copiaron a /img/wp/ espejando la ruta original,
-- por eso basta con reemplazar el prefijo.
--
-- Sin esto, el dia del cambio de dominio esas imagenes desaparecen.
-- =====================================================================

SET NAMES utf8mb4;

-- solutions
UPDATE `solutions` SET `hero_image`=REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`hero_image`,'https://aldea.work/wp-content/uploads/','/img/wp/'),'https://www.aldea.work/wp-content/uploads/','/img/wp/'),'http://aldea.work/wp-content/uploads/','/img/wp/'),'http://www.aldea.work/wp-content/uploads/','/img/wp/'),'https:\\/\\/aldea.work\\/wp-content\\/uploads\\/','\\/img\\/wp\\/'),'https:\\/\\/www.aldea.work\\/wp-content\\/uploads\\/','\\/img\\/wp\\/') WHERE `hero_image` LIKE '%wp-content%';
