UPDATE `solutions` SET `body_es`=REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`body_es`,'https://aldea.work/wp-content/uploads/','/img/wp/'),'https://www.aldea.work/wp-content/uploads/','/img/wp/'),'http://aldea.work/wp-content/uploads/','/img/wp/'),'http://www.aldea.work/wp-content/uploads/','/img/wp/'),'https:\\/\\/aldea.work\\/wp-content\\/uploads\\/','\\/img\\/wp\\/'),'https:\\/\\/www.aldea.work\\/wp-content\\/uploads\\/','\\/img\\/wp\\/') WHERE `body_es` LIKE '%wp-content%';
UPDATE `solutions` SET `body_en`=REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`body_en`,'https://aldea.work/wp-content/uploads/','/img/wp/'),'https://www.aldea.work/wp-content/uploads/','/img/wp/'),'http://aldea.work/wp-content/uploads/','/img/wp/'),'http://www.aldea.work/wp-content/uploads/','/img/wp/'),'https:\\/\\/aldea.work\\/wp-content\\/uploads\\/','\\/img\\/wp\\/'),'https:\\/\\/www.aldea.work\\/wp-content\\/uploads\\/','\\/img\\/wp\\/') WHERE `body_en` LIKE '%wp-content%';

